FROZEN TOOL AND TASK CONTRACT:
{
  "version": "EX0004B_PUBLIC_GUIDE_V1",
  "architecture": [
    6,
    12,
    12,
    1
  ],
  "task": "Continuous prediction; x5 is a nuisance input.",
  "patient": "Two planted fault groups in different hidden layers; four altered scalar parameters total.",
  "diagnostic_tools": {
    "weights": {
      "fields": [
        "tool",
        "tensor",
        "start",
        "count"
      ],
      "count_range": [
        1,
        24
      ],
      "example": {
        "tool": "weights",
        "tensor": "fc1.weight",
        "start": 0,
        "count": 6
      }
    },
    "examples": {
      "fields": [
        "tool",
        "regime",
        "indices"
      ],
      "example": {
        "tool": "examples",
        "regime": "shift",
        "indices": [
          0,
          1
        ]
      }
    },
    "activations": {
      "fields": [
        "tool",
        "regime"
      ],
      "example": {
        "tool": "activations",
        "regime": "shift"
      }
    },
    "counterfactual": {
      "fields": [
        "tool",
        "regime",
        "indices",
        "x5"
      ],
      "example": {
        "tool": "counterfactual",
        "regime": "shift",
        "indices": [
          0,
          1
        ],
        "x5": 0.0
      }
    }
  },
  "tensor_shapes": {
    "fc1.weight": [
      12,
      6
    ],
    "fc1.bias": [
      12
    ],
    "fc2.weight": [
      12,
      12
    ],
    "fc2.bias": [
      12
    ],
    "readout.weight": [
      1,
      12
    ],
    "readout.bias": [
      1
    ]
  },
  "diagnosis_fields": [
    "tool",
    "fault_A",
    "fault_B",
    "predictions",
    "confidence",
    "mechanism",
    "initial_patch"
  ],
  "diagnosis_predictions": {
    "isolated_effect_rank": [
      "A_gt_B",
      "B_gt_A"
    ],
    "interaction_sign": [
      "positive",
      "negative"
    ],
    "nuisance_restoration": [
      "decrease",
      "increase",
      "unchanged"
    ]
  },
  "patch_format": {
    "fields": [
      "tensor",
      "index",
      "delta"
    ],
    "max_edits": 6,
    "max_abs_delta": 20.0,
    "empty_patch_means_abstain": true
  },
  "repair_actions": {
    "patch_trial": {
      "tool": "patch_trial",
      "edits": [
        {
          "tensor": "fc1.weight",
          "index": [
            0,
            5
          ],
          "delta": -0.1
        }
      ]
    },
    "submit_patch": {
      "tool": "submit_patch",
      "edits": []
    }
  },
  "rules": {
    "one_json_action_per_turn": true,
    "diagnostic_calls_max": 12,
    "patch_trials_max": 2,
    "scalar_edits_max": 6,
    "diagnosis_before_patch_feedback": true,
    "patch_deltas_relative_to_corrupted_baseline": true,
    "diagnosis_submission_costs_zero_probes": true,
    "no_healthy_weights_or_oracle_access": true,
    "no_arbitrary_python_or_filesystem_access": true
  },
  "diagnosis_submission_example": {
    "tool": "submit_diagnosis",
    "fault_A": {
      "layer": "fc1",
      "neuron": 0,
      "input_feature": 0
    },
    "fault_B": {
      "layer": "fc2",
      "neuron": 0,
      "source_neuron": 0
    },
    "predictions": {
      "isolated_effect_rank": "A_gt_B",
      "interaction_sign": "positive",
      "nuisance_restoration": "unchanged"
    },
    "confidence": 0.5,
    "mechanism": "FORMAT EXAMPLE ONLY. Not a diagnosis.",
    "initial_patch": []
  },
  "allowed_actions": [
    "weights",
    "examples",
    "activations",
    "counterfactual",
    "submit_diagnosis",
    "patch_trial",
    "submit_patch"
  ],
  "phase_rule": "patch_trial and submit_patch are unavailable until submit_diagnosis is accepted.",
  "patch_trial_example": {
    "tool": "patch_trial",
    "edits": [
      {
        "tensor": "readout.bias",
        "index": [
          0
        ],
        "delta": 0.01
      }
    ]
  },
  "final_patch_example": {
    "tool": "submit_patch",
    "edits": []
  },
  "example_warning": "Examples demonstrate syntax only. They are not observations, diagnoses or recommended repairs."
}

